window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-726ca9f76956c2ae"]={"versions": [{"id": "FIG-726ca9f76956c2ae", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-5c3b3b07f0123107", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-ef66f4a9fad5a4f7", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-00a9ab3fdaea9ac1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-57490a32cfcf50c6", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-9c09a5a532af3b96", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-8212e5d751085f98", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-de238403ad760716", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-c74dab8e338b8cd7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}, {"id": "FIG-0b9e301bd8e52364", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mechatronische Systemtopologie und Signalflussarchitektur (Physical Architecture & Control Flow Diagram) für Lenksysteme im Rahmen der AUTOSAR-Chassis-Domäne (<code>AUTOSAR_EXP_AIChassis</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der physischen Wirkkette, Sensorpositionen, Aktuator-Integrationspunkte und Drehmoment-Summationspfade zur Ableitung standardisierter AUTOSAR-Software-Components (SWCs), Sender-Receiver-Interfaces und Port-Definitionen für:</li>\n<li>Elektrische Servolenkung (EPS / BSTS – <em>Base Steering Torque System</em>) in verschiedenen Bauformen (Column, Pinion, Dual Pinion, Rack/Belt/Concentric Drive).</li>\n<li>Aktive Überlagerungslenkung (AFS / BSAS – <em>Base Steering Angle System</em>).</li>\n<li><strong>Einordnung im AUTOSAR-Gesamtsystem:</strong> Dient als normative Domänen-Referenz zur Spezifikation von Applikationsschnittstellen (AI Chassis). Es definiert die physikalische Basis für die Abstraktion zwischen fahrzeugspezifischer Aktorik/Sensorik (Sensor/Actuator-SWCs, IoHwAb, MCAL) und standardisierten Regelungs-SWCs (Application Layer).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### A. Mechanische Wirkkette & Kinematik</p>\n<ul class=\"fig-list\">\n<li><strong>Lenkrad (Steering Wheel):</strong> Mechanischer Schnittpunkt für das Fahrermoment ($T_{\\text{DriverTorque}}$) und den Fahrerlenkwinkel.</li>\n<li><strong>Überlagerungsgetriebe (<code>X</code>):</strong> Planeten-/Differentialgetriebe zur winkelmäßigen Überlagerung von Fahrerlenkwinkel und Aktuatorwinkel.</li>\n<li><strong>Lenksäule & Gelenke:</strong> Übertragungswelle mit oberem und unterem Kardangelenk (<code>Upper/Lower Cardan Joint</code>) inklusive Drehspiel- und Drehmomentmodulation (<code>Clearance / Torque Modulation</code>).</li>\n<li><strong>Zahnstangengetriebe (<code>Steering Rack</code>):</strong> Wandelt Drehbewegung in Translationsbewegung; wirkt mit Zahnstangenkraft ($F_{\\text{Rack Force}}$) auf Spurstangen (<code>Tie Rod / Steering Link</code>) und Spurstangenhebel (<code>Steering Lever</code>).</li>\n<li><strong>Vorderräder (<code>Wheel Front Left / Right</code>):</strong> Krafteinleitungspunkt der Straßenkräfte ($T_{\\text{Road Wheel Torque}}$).</li>\n</ul>\n<p class=\"fig-p\">#### B. Aktuator- und Sensor-Entitäten (SWC- & HW-Klassen)</p>\n<ul class=\"fig-list\">\n<li><strong>BSAS Actuator (Base Steering Angle System):</strong></li>\n<li><em>Funktion:</em> Aktive Winkelüberlagerung am Getriebe <code>X</code>.</li>\n<li><em>Sensorik:</em> <code>Pos. Sensor</code> (misst <code>Measured Sum Steer Angle</code>) und <code>(Virt.) Pos. Sensor</code> (liefert <code>Sum Steer Angle</code>).</li>\n<li><em>Aktorik:</em> Motor erzeugt <code>Motor Torque</code> zur Winkelverstellung.</li>\n<li><strong>BSTS Actuatoren (Base Steering Torque System – EPS-Varianten):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Column Drive Actuator (C-EPS):</strong> Eingriff an der Lenksäule.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Steering Wheel Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Steering Wheel Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pinion Drive Actuator (P-EPS):</strong> Eingriff direkt am Lenkritzel.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Dual Pinion Actuator (DP-EPS):</strong> Eingriff über ein zweites, separates Ritzel auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Torque Sensor</code> $\\rightarrow$ <code>Pinion Torque</code>; <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concentric Drive Actuator (R-EPS koaxial):</strong> Direktantrieb auf der Zahnstange.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Pinion Angle</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Belt Drive Actuator (R-EPS Riemen-/Kugelgewindetrieb):</strong> Antrieb der Zahnstangenmutter via Zahnriemen.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Sensorik:</em> <code>Ang. Pos. Sensor</code> $\\rightarrow$ <code>Virt. Pinion Angle / Virt. Rack Displacement</code>.</li>\n</ul>\n<p class=\"fig-p\">#### C. Schnittstellen & Datenstrukturen (AUTOSAR Port Interfaces)</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-Receiver-Interfaces (<code>«isOfType» SenderReceiverInterface</code>):</strong></li>\n<li>Drehmoment-Ports: Datentyp mit SI-Einheit $\\text{Nm}$ (<code>TDriverTorque</code>, <code>TMotorTorque</code>, <code>TPinionTorque</code>, <code>TRoadWheelTorque</code>).</li>\n<li>Winkel-Ports: Datentyp mit SI-Einheit $\\text{rad}$ oder $\\text{deg}$ (<code>SteeringWheelAngle</code>, <code>PinionAngle</code>, <code>SumSteerAngle</code>).</li>\n<li>Kraft-Ports: Datentyp mit SI-Einheit $\\text{N}$ (<code>RackForce</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Signalfluss: Interne Drehmoment-Kette (<em>Internal Torque Definitions</em>)</p>\n<ol class=\"fig-list\">\n<li><strong>Momenten-Summation:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{total torque}} = T_{\\text{DriverTorque}} + (T_{\\text{delta steering torque}} \\lor T_{\\text{absolute steering torque}})$$</p>\n<ul class=\"fig-list\">\n<li>$T_{\\text{delta steering torque}}$: Relativer Momenteneingriff (z. B. Spurhalteassistent / LKA).</li>\n<li>$T_{\\text{absolute steering torque}}$: Absoluter Momenteneingriff (z. B. autonomes Parken / evasive steer assist).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Unterstützungskennfeld / Boost-Kurve:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{AssistanceTorque}} = f(T_{\\text{total torque}}, v)$$</p>\n<ul class=\"fig-list\">\n<li>Berechnung des Soll-Unterstützungsmoments in Abhängigkeit vom Gesamtmoment und der Fahrzeuggeschwindigkeit $v$.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktuator-Momentenregelung:</strong></li>\n</ol>\n<p class=\"fig-p\">$$T_{\\text{Motor Torque}} = f(T_{\\text{AssistanceTorque}})$$</p>\n<ul class=\"fig-list\">\n<li>Dynamische Wandlung unter Berücksichtigung von Massenträgheit, Reibungskompensation, Dämpfung und Motorkennfeld in das elektrische Soll-Motormoment $T_{\\text{Motor Torque}}$.</li>\n</ul>\n<p class=\"fig-p\">#### Synchronisations- & Abtastanforderungen</p>\n<ul class=\"fig-list\">\n<li><strong>Harte Echtzeit:</strong> Der Drehmomentregelkreis (Messung $\\rightarrow$ Kennfeldberechnung $\\rightarrow$ Motorstromstellung via MCAL PWM/ADC) wird typischerweise in Task-Zyklen von $t \\le 1\\,\\text{ms}$ bis $2\\,\\text{ms}$ synchron ausgeführt.</li>\n<li><strong>Winkelüberlagerung (BSAS):</strong> Trajektorienplanung und Winkelregelung laufen in Zyklen von $5\\,\\text{ms}$ bis $10\\,\\text{ms}$.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC-Port-Standardisierung:</strong> Applikations-SWCs dürfen nicht hardwarenah auf spezifische EPS-Bauformen (C-EPS vs. R-EPS) zugeschnitten sein. Die Kapselung der spezifischen Kinematik (z. B. Umrechnung <em>Rack Displacement</em> in <em>Pinion Angle</em>) hat in Sensor-/Actuator-SWCs oder Abstraktionsschichten zu erfolgen.</li>\n<li><strong>Virtuelle Sensorik & Schätzer:</strong> Das Diagramm spezifiziert explizit virtuelle Sensoren (<code>(Virt.) Pos. Sensor</code>, <code>Virt. Pinion Angle</code>). Embedded-Entwickler müssen hierfür modellbasierte Beobachter (z. B. Kalman-Filter oder Luenberger-Beobachter auf Basis von Motorgeber-Signalen) in den SWCs vorsehen.</li>\n<li><strong>Funktionale Sicherheit (ISO 26262 – ASIL D):</strong></li>\n<li>Lenksysteme erfordern redundante Sensorerfassung (z. B. Vergleich <code>Measured Sum Steer Angle</code> vs. <code>Sum Steer Angle</code> sowie Drehmoment-Plausibilisierung).</li>\n<li>Externe Momenteneingriffe ($T_{\\text{delta}}$, $T_{\\text{absolute}}$) über Bussysteme (CAN/FlexRay/Ethernet) erfordern zwingend AUTOSAR E2E-Protection (CRC, Sequence Counter) im COM-Stack.</li>\n<li>Bei Drehmomentbegrenzungsfehlern oder unplausiblen Winkeln greift das Sicherheitskonzept mit Rückfallebene (Ramp-down des Assistenzmoments, Abschaltung BSAS, Beibehaltung der mechanischen Durchkopplung).</li>\n<li><strong>RTE-Mapping & Skalierung:</strong> Einheiten müssen den AUTOSAR-CompuMethods entsprechen (standardisiert auf physikalische SI-Einheiten, vorzeichenbehaftete Festkomma- oder Fließkommaformate zur Vermeidung von Quantisierungsverlusten in der Drehmomentsumme).</li>\n</ul>"}], "trans": [{"from": "FIG-726ca9f76956c2ae", "to": "FIG-5c3b3b07f0123107", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Steering Rack</code>: Grafische Überarbeitung der Zahnstange; die zuvor einfarbig gefüllte Leiste wurde durch eine schraffierte Darstellung (symbolische Zahnstangenverzahnung) ersetzt. Alle Schnittstellen, Bezeichner, Sensoren und Aktuatoren bleiben unverändert.</li>\n</ul>"}, {"from": "FIG-5c3b3b07f0123107", "to": "FIG-ef66f4a9fad5a4f7", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ef66f4a9fad5a4f7", "to": "FIG-00a9ab3fdaea9ac1", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-00a9ab3fdaea9ac1", "to": "FIG-57490a32cfcf50c6", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-57490a32cfcf50c6", "to": "FIG-9c09a5a532af3b96", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9c09a5a532af3b96", "to": "FIG-8212e5d751085f98", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8212e5d751085f98", "to": "FIG-de238403ad760716", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-de238403ad760716", "to": "FIG-c74dab8e338b8cd7", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c74dab8e338b8cd7", "to": "FIG-0b9e301bd8e52364", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
